-- [S3] Air emissions (EIS, TRI, GHGRP, CAMD combined) for the 18 registry IDs, by registry, program, year, pollutant
SELECT TO_VARCHAR(REGISTRY_ID) AS REG, PGM_SYS_ACRNM, REPORTING_YEAR, POLLUTANT_NAME, UNIT_OF_MEASURE, SUM(ANNUAL_EMISSION) AS EM, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS
WHERE TO_VARCHAR(REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602')
GROUP BY 1,2,3,4,5 ORDER BY 1,2,3,4
